// Generates features/collect/wf1-collect.json (credential names only, no IDs).
const fs = require('fs');
const { randomUUID: id } = require('crypto');
const REPO = '/home/krishaanth/Desktop/personal_projects/github/prosus-hackathon';
const OUT = `${REPO}/features/collect/wf1-collect.json`;

// keep node/webhook ids stable across regenerations
const prev = fs.existsSync(OUT) ? JSON.parse(fs.readFileSync(OUT, 'utf8')) : { nodes: [] };
const prevNode = (name) => prev.nodes.find((n) => n.name === name) ?? {};

const binCells = fs.readFileSync(`${REPO}/features/collect/binCells.js`, 'utf8');
const jsCode = binCells + 'return binCells($input.all().map(i => i.json)).map(json => ({ json }));\n';

const apify = { httpHeaderAuth: { name: 'AirGuard Apify' } };
const pg = { postgres: { name: 'AirGuard Postgres' } };
const META = "$('Get RUN_META').first().json";
const RUN = "$('Apify run succeeded').first().json.body.resource";
const set = (fields) => ({
  mode: 'manual',
  assignments: { assignments: Object.entries(fields).map(([name, value]) => ({ id: id(), name, value, type: 'string' })) },
  options: {},
});
const pgInsert = (table) => ({
  schema: { __rl: true, mode: 'list', value: 'public' },
  table: { __rl: true, mode: 'name', value: table },
  columns: { mappingMode: 'autoMapInputData', value: {}, matchingColumns: [], schema: [] },
  options: {},
});
const ifTrue = (leftValue, operator) => ({
  conditions: {
    options: { caseSensitive: true, leftValue: '', typeValidation: 'loose', version: 2 },
    conditions: [{ id: id(), leftValue, rightValue: '', operator }],
    combinator: 'and',
  },
  options: {},
});

const nodes = [
  { name: 'Apify run succeeded', type: 'n8n-nodes-base.webhook', typeVersion: 2, position: [0, 300],
    webhookId: prevNode('Apify run succeeded').webhookId ?? id(),
    parameters: { httpMethod: 'POST', path: 'airguard-apify', responseMode: 'onReceived', options: {} } },
  { name: 'Config', type: 'n8n-nodes-base.set', typeVersion: 3.4, position: [220, 300],
    parameters: set({ apify_api: 'https://api.apify.com/v2' }) },
  { name: 'Get RUN_META', type: 'n8n-nodes-base.httpRequest', typeVersion: 4.2, position: [440, 300],
    parameters: { url: `={{ $('Config').first().json.apify_api }}/key-value-stores/{{ ${RUN}.defaultKeyValueStoreId }}/records/RUN_META`,
      authentication: 'genericCredentialType', genericAuthType: 'httpHeaderAuth', options: {} },
    credentials: apify },
  { name: 'Get dataset items', type: 'n8n-nodes-base.httpRequest', typeVersion: 4.2, position: [660, 300], alwaysOutputData: true,
    parameters: { url: `={{ $('Config').first().json.apify_api }}/datasets/{{ ${RUN}.defaultDatasetId }}/items?clean=true`,
      authentication: 'genericCredentialType', genericAuthType: 'httpHeaderAuth', options: {} },
    credentials: apify },
  { name: 'binCells', type: 'n8n-nodes-base.code', typeVersion: 2, position: [880, 300], alwaysOutputData: true,
    parameters: { jsCode } },
  { name: 'Any cells?', type: 'n8n-nodes-base.if', typeVersion: 2.2, position: [1100, 300],
    parameters: ifTrue('={{ $json.cell_id }}', { type: 'string', operation: 'exists', singleValue: true }) },
  { name: 'Insert observations', type: 'n8n-nodes-base.postgres', typeVersion: 2.5, position: [1320, 200],
    parameters: pgInsert('observations'), credentials: pg },
  { name: 'Failover?', type: 'n8n-nodes-base.if', typeVersion: 2.2, position: [1540, 100], executeOnce: true,
    parameters: ifTrue(`={{ ${META}.failover }}`, { type: 'boolean', operation: 'true', singleValue: true }) },
  { name: 'Failover line', type: 'n8n-nodes-base.set', typeVersion: 3.4, position: [1760, 100],
    parameters: set({
      workflow: 'WF1',
      action: `={{ 'SWITCH SOURCE TO ' + ${META}.source.toUpperCase() }}`,
      reason: `={{ 'primary adsb.lol unavailable (' + (${META}.errors.join('; ') || 'no aircraft returned') + '), switched to ' + ${META}.source }}`,
      outcome: `={{ ${META}.aircraft + ' aircraft from ' + ${META}.source + ', ' + $('binCells').all().length + ' cells written' }}`,
    }) },
  { name: 'Log failover', type: 'n8n-nodes-base.postgres', typeVersion: 2.5, position: [1980, 100],
    parameters: pgInsert('agent_log'), credentials: pg },
  { name: 'No data line', type: 'n8n-nodes-base.set', typeVersion: 3.4, position: [1320, 420],
    parameters: set({
      workflow: 'WF1',
      action: 'FLAG NO DATA',
      reason: `={{ 'no data from any source: every cell UNKNOWN (' + (${META}.errors.join('; ') || (${META}.aircraft ? ${META}.aircraft + ' aircraft, none with NIC/NACp' : 'sources answered with 0 aircraft')) + ')' }}`,
      outcome: 'no observations written this cycle',
    }) },
  { name: 'Log no data', type: 'n8n-nodes-base.postgres', typeVersion: 2.5, position: [1540, 420],
    parameters: pgInsert('agent_log'), credentials: pg },
  { name: 'Execute WF2', type: 'n8n-nodes-base.executeWorkflow', typeVersion: 1.2, position: [1760, 320],
    disabled: true, executeOnce: true, notes: 'wire at integration', notesInFlow: true,
    parameters: { workflowId: { __rl: true, mode: 'list', value: '' }, options: {} } },
].map((n) => ({ id: prevNode(n.name).id ?? id(), ...n }));

const link = (...targets) => ({ main: targets.map((t) => (t ? [].concat(t).map((node) => ({ node, type: 'main', index: 0 })) : [])) });
const connections = {
  'Apify run succeeded': link('Config'),
  Config: link('Get RUN_META'),
  'Get RUN_META': link('Get dataset items'),
  'Get dataset items': link('binCells'),
  binCells: link('Any cells?'),
  'Any cells?': link('Insert observations', 'No data line'),
  'Insert observations': link(['Failover?', 'Execute WF2']),
  'Failover?': link('Failover line', null),
  'Failover line': link('Log failover'),
  'No data line': link('Log no data'),
  'Log no data': link('Execute WF2'),
};

const wf = { name: 'AirGuard WF1 Collect', nodes, connections, settings: { executionOrder: 'v1' } };
fs.writeFileSync(OUT, JSON.stringify(wf, null, 2) + '\n');
console.log(`wrote ${OUT}: ${nodes.length} nodes`);

// usage: node n8n-import.cjs <workflow.json> [--id <existing id>] [--activate]
//          [--config name=value ...]   override a value in the "Config" node (values kept out of the repo)
//          [--setting name=value ...]  e.g. errorWorkflow=<WF4 id>
// Resolves credentials by name + type to their IDs, then creates or updates the workflow.
const fs = require('fs');
const base = process.env.N8N_BASE_URL.replace(/\/$/, '');

async function api(method, path, body) {
  const res = await fetch(`${base}/api/v1${path}`, {
    method,
    headers: { 'X-N8N-API-KEY': process.env.N8N_API_KEY, 'content-type': 'application/json', accept: 'application/json' },
    body: body ? JSON.stringify(body) : undefined,
  });
  const text = await res.text();
  if (!res.ok) throw new Error(`${method} ${path}: HTTP ${res.status} ${text.slice(0, 800)}`);
  return text ? JSON.parse(text) : {};
}

(async () => {
  const [file, ...args] = process.argv.slice(2);
  const opt = (flag) => args.flatMap((a, i) => (a === flag ? [args[i + 1]] : []));
  const wf = JSON.parse(fs.readFileSync(file, 'utf8'));

  for (const kv of opt('--config')) {
    const [name, ...rest] = kv.split('=');
    const a = wf.nodes.find((n) => n.name === 'Config').parameters.assignments.assignments.find((x) => x.name === name);
    if (!a) throw new Error(`Config has no field ${name}`);
    a.value = rest.join('=');
  }
  const settings = { ...wf.settings };
  for (const kv of opt('--setting')) { const [k, ...v] = kv.split('='); settings[k] = v.join('='); }

  const creds = (await api('GET', '/credentials?limit=100')).data;
  for (const n of wf.nodes) {
    for (const [type, ref] of Object.entries(n.credentials ?? {})) {
      const c = creds.find((x) => x.name === ref.name && x.type === type);
      if (!c) throw new Error(`node "${n.name}": no credential "${ref.name}" of type ${type}`);
      n.credentials[type] = { id: c.id, name: c.name };
    }
  }

  const body = { name: wf.name, nodes: wf.nodes, connections: wf.connections, settings };
  const [id] = opt('--id');
  const saved = id ? await api('PUT', `/workflows/${id}`, body) : await api('POST', '/workflows', body);
  let active = saved.active;
  if (args.includes('--activate')) active = (await api('POST', `/workflows/${saved.id}/activate`)).active;
  console.log(JSON.stringify({ id: saved.id, name: saved.name, active, nodes: saved.nodes.length }));
})().catch((e) => { console.error(e.message); process.exit(1); });

