// usage: node n8n-import.cjs <workflow.json> [--id <existing id>] [--activate]
//          [--config name=value ...]   override a value in the "Config" node (values kept out of the repo)
//          [--setting name=value ...]  e.g. errorWorkflow=<WF4 id>
// Resolves credentials by name + type to their IDs, then creates or updates the workflow.
const fs = require('fs');
const base = process.env.N8N_BASE_URL.replace(/\/$/, '');

async function api(method, path, body) {
  const res = await fetch(`${base}/api/v1${path}`, {
    method,
    headers: { 'X-N8N-API-KEY': process.env.N8N_API_KEY, 'content-type': 'application/json', accept: 'application/json' },
    body: body ? JSON.stringify(body) : undefined,
  });
  const text = await res.text();
  if (!res.ok) throw new Error(`${method} ${path}: HTTP ${res.status} ${text.slice(0, 800)}`);
  return text ? JSON.parse(text) : {};
}

(async () => {
  const [file, ...args] = process.argv.slice(2);
  const opt = (flag) => args.flatMap((a, i) => (a === flag ? [args[i + 1]] : []));
  const wf = JSON.parse(fs.readFileSync(file, 'utf8'));

  for (const kv of opt('--config')) {
    const [name, ...rest] = kv.split('=');
    const a = wf.nodes.find((n) => n.name === 'Config').parameters.assignments.assignments.find((x) => x.name === name);
    if (!a) throw new Error(`Config has no field ${name}`);
    a.value = rest.join('=');
  }
  const settings = { ...wf.settings };
  for (const kv of opt('--setting')) { const [k, ...v] = kv.split('='); settings[k] = v.join('='); }

  const creds = (await api('GET', '/credentials?limit=100')).data;
  for (const n of wf.nodes) {
    for (const [type, ref] of Object.entries(n.credentials ?? {})) {
      const c = creds.find((x) => x.name === ref.name && x.type === type);
      if (!c) throw new Error(`node "${n.name}": no credential "${ref.name}" of type ${type}`);
      n.credentials[type] = { id: c.id, name: c.name };
    }
  }

  const body = { name: wf.name, nodes: wf.nodes, connections: wf.connections, settings };
  const [id] = opt('--id');
  const saved = id ? await api('PUT', `/workflows/${id}`, body) : await api('POST', '/workflows', body);
  let active = saved.active;
  if (args.includes('--activate')) active = (await api('POST', `/workflows/${saved.id}/activate`)).active;
  console.log(JSON.stringify({ id: saved.id, name: saved.name, active, nodes: saved.nodes.length }));
})().catch((e) => { console.error(e.message); process.exit(1); });

