// usage: node export-wf.cjs <workflowId> <repo file> [--write]
// Re-exports a live n8n workflow into its committed file with the smallest honest diff:
// every node, the connections and the settings are compared with the committed copy; only what differs
// is replaced by the live version. Credential IDs are dropped and the Config node keeps the repo's
// placeholder values (real chat ids / allowlists / sheet ids never reach the public repo).
const fs = require('fs');
const assert = require('assert');
const base = process.env.N8N_BASE_URL.replace(/\/$/, '');

const sanitize = (n) => {
  const c = JSON.parse(JSON.stringify(n));
  for (const ref of Object.values(c.credentials ?? {})) delete ref.id;
  return c;
};
const same = (a, b) => { try { assert.deepStrictEqual(a, b); return true; } catch { return false; } };

(async () => {
  const [id, file, flag] = process.argv.slice(2);
  const r = await fetch(`${base}/api/v1/workflows/${id}`, { headers: { 'X-N8N-API-KEY': process.env.N8N_API_KEY } });
  if (!r.ok) throw new Error(`GET ${id}: ${r.status}`);
  const live = await r.json();
  const repo = JSON.parse(fs.readFileSync(file, 'utf8'));
  const changes = [];

  assert.equal(live.name, repo.name, 'same workflow');
  const liveNames = live.nodes.map((n) => n.name).sort(), repoNames = repo.nodes.map((n) => n.name).sort();
  if (!same(liveNames, repoNames)) throw new Error(`node sets differ:\n live ${liveNames}\n repo ${repoNames}`);

  repo.nodes = repo.nodes.map((rn) => {
    const ln = sanitize(live.nodes.find((n) => n.name === rn.name));
    if (rn.name === 'Config') {                       // keep the repo's placeholders, compare only the field names
      const names = (n) => n.parameters.assignments.assignments.map((a) => a.name);
      if (!same(names(ln), names(rn))) changes.push('Config (field names differ, NOT copied: check by hand)');
      return rn;
    }
    if (same(ln, rn)) return rn;
    changes.push(rn.name);
    return ln;
  });
  if (!same(live.connections, repo.connections)) { changes.push('connections'); repo.connections = live.connections; }
  if (!same(live.settings, repo.settings)) { changes.push(`settings ${JSON.stringify(repo.settings)} -> ${JSON.stringify(live.settings)}`); repo.settings = live.settings; }

  console.log(`${repo.name}: ${changes.length ? 'changed: ' + changes.join(' | ') : 'no changes'}`);
  if (flag === '--write') fs.writeFileSync(file, JSON.stringify(repo, null, 2) + '\n');
})().catch((e) => { console.error(e.message); process.exit(1); });

