  assert.match(droneReport(ok(), END - 3600e3).log.reason, /in the future/);
  assert.match(droneReport({ ...ok(), samples: Array(20001).fill(ok().samples[0]) }, NOW).log.reason, /needs 1 to 20000 samples/);
});

